rules.logic:
// Find the Afbeeldingen block (ULSxyf containing heading "Afbeeldingen")
let afbeeldingenBlock = null;
let videosBlock = null;

const candidates = element.querySelectorAll('.ULSxyf');
for (const block of candidates) {
  const heading = block.querySelector('.mgAbYb, [role="heading"]');
  if (heading) {
    const text = heading.textContent.trim();
    if (text === 'Afbeeldingen') afbeeldingenBlock = block;
    if (text === "Video's") videosBlock = block;
  }
}

if (!afbeeldingenBlock && !videosBlock) return;

// Insert both at the very top of #rso, Videos first then Afbeeldingen
// so reading order is: Afbeeldingen, then Video's at the top
const firstChild = element.firstChild;

if (videosBlock && videosBlock !== firstChild) {
  element.insertBefore(videosBlock, firstChild);
}
if (afbeeldingenBlock) {
  element.insertBefore(afbeeldingenBlock, element.firstChild);
}
